import java.util.Scanner;

public class Main {
    static final long mod = 1000000007L;
    static int K;
    static long N;
    static Matrix[] a = new Matrix[70];
    static Matrix[] prefix = new Matrix[70];
    static Matrix[] suffix = new Matrix[70];
    static Matrix identity = new Matrix();
    static Matrix result = new Matrix();

    static class Matrix {
        int[][] m = new int[33][33];

        Matrix() {
            for (int i = 0; i < 33; i++) {
                for (int j = 0; j < 33; j++) {
                    m[i][j] = 0;
                }
            }
        }
    }

    static void printMatrix(Matrix x) {
        for (int i = 0; i <= K; i++) {
            for (int j = 0; j <= K; j++) {
                System.out.print(x.m[i][j] + " ");
            }
            System.out.println();
        }
        System.out.println();
    }

    static Matrix multiply(Matrix a, Matrix b) {
        Matrix c = new Matrix();
        for (int i = 0; i <= K; i++) {
            for (int j = 0; j <= K; j++) {
                long tmp = 0;
                for (int k = 0; k <= K; k++) {
                    tmp += (long) a.m[i][k] * b.m[k][j];
                }
                c.m[i][j] = (int) (tmp % mod);
            }
        }
        return c;
    }

    static void computePrefixSuffix() {
        int i;
        prefix[0] = a[0];
        for (i = 1; i < K; i++) {
            prefix[i] = multiply(prefix[i - 1], a[i]);
        }
        suffix[K - 1] = a[K - 1];
        for (i = K - 2; i >= 0; i--) {
            suffix[i] = multiply(a[i], suffix[i + 1]);
        }
        a[0] = suffix[0];
        for (i = 1; i < K; i++) {
            a[i] = multiply(suffix[i], prefix[i - 1]);
        }
    }

    static void process(Scanner sc) {
        N = sc.nextLong();
        K = sc.nextInt();

        result = new Matrix();
        for (int i = 0; i < K; i++) {
            a[i] = new Matrix();
            for (int j = 0; j <= K; j++) {
                a[i].m[j][j] = 1;
            }
            for (int j = 0; j <= K; j++) {
                a[i].m[j][i] = 1;
            }
            result.m[i][i] = 1;
        }
        result.m[K][K] = 1;

        while (N > 0) {
            int t = (int) (N % K);
            if (t != 0) {
                long pos = 0, tmp = N;
                while (tmp != 0) {
                    tmp /= K;
                    pos = (pos + tmp) % K;
                }
                for (int i = t - 1; i >= 0; i--) {
                    result = multiply(a[(int) ((pos + i) % K)], result);
                }
            }
            computePrefixSuffix();
            N /= K;
        }

        int answer = 1;
        for (int i = 0; i < K; i++) {
            answer = (answer + result.m[K][i]) % (int) mod;
        }
        System.out.println(answer);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        process(sc);
        sc.close();
    }
}

